mapper.update:
UPDATE crm_receivable SET owner_id = #{record.ownerId}, owner_name = #{record.ownerName},
    version = version + 1, update_by = #{record.updateBy}, update_time = #{record.updateTime}
WHERE receivable_id = #{record.receivableId} AND tenant_id = #{record.tenantId} AND version = #{expectedVersion} AND deleted = 0

mapper.select:
SELECT t.receivable_id, t.tenant_id, t.customer_id, t.customer_name, t.contract_id, t.contract_no, t.receivable_no, t.receivable_name, t.planned_amount, t.received_amount, t.outstanding_amount, t.due_date, t.received_date, t.invoice_status, t.invoice_id, t.owner_id, t.owner_name, t.remark, t.status, t.deleted, t.version, , t.create_by, t.create_time, t.update_by, t.update_time, c.dept_id AS scope_dept_id, c.owner_id AS scope_owner_id FROM crm_receivable t INNER JOIN crm_customer c ON c.customer_id = t.customer_id AND c.tenant_id = t.tenant_id AND c.deleted = '0' WHERE t.deleted = '0'
AND t.customer_id = #{query.customerId}
AND t.contract_id = #{query.contractId}
AND t.receivable_name LIKE CONCAT('%', #{query.receivableName}, '%')
AND t.status = #{query.status}
ORDER BY t.update_time DESC
